/* Unsubmitted text is a local draft, not an implicit synchronization. */
(()=>{'use strict';const key='goblin-editor-drafts-v1';let drafts={};try{drafts=JSON.parse(localStorage.getItem(key)||'{}')}catch(_){}
 const context=()=>JSON.stringify([state.page,state.page==='connected'?tab:'',state.page==='jdr'&&typeof jdrEdit==='string'?jdrEdit:'',state.page==='mental'?mentalCategory:'',state.page==='grimoire'&&typeof openedRecipeId==='string'?openedRecipeId:'']);
 const fields=root=>[...root.querySelectorAll('input,textarea,select')].filter(n=>!['file','password','checkbox','radio','button','submit','search'].includes(n.type));
 function signature(node){const card=node.closest('[data-mental-card]')?.dataset.mentalCard||'',name=node.getAttribute('aria-label')||node.getAttribute('placeholder')||node.name||node.id||node.type;const peers=fields(node.closest('[data-mental-card]')||document.getElementById('content')).filter(n=>(n.getAttribute('aria-label')||n.getAttribute('placeholder')||n.name||n.id||n.type)===name);return card+'|'+name+'|'+peers.indexOf(node)}
 function persist(){try{localStorage.setItem(key,JSON.stringify(drafts))}catch(_){const subtitle=document.getElementById('subtitle');if(subtitle)subtitle.textContent='Le brouillon ne peut pas être enregistré. Garde cette page ouverte et copie ton texte.'}}
 function restore(){const root=document.getElementById('content'),saved=drafts[context()]||{};if(!root)return;let count=0;for(const node of fields(root)){const value=saved[signature(node)];if(typeof value==='string'){node.value=value;count++}}if(count&&!root.querySelector('#editorDraftNotice')){const box=el('div',{class:'panel',id:'editorDraftNotice',role:'status'});box.append(el('p',{class:'muted'},'Brouillon local retrouvé. Tes champs ne sont partagés qu’après leur enregistrement.'));const clear=el('button',{class:'action'},'Effacer le brouillon de cette page');clear.onclick=()=>{if(!confirm('Effacer les champs non enregistrés de cette page ?'))return;delete drafts[context()];persist();render()};box.append(clear);root.prepend(box)}
   const others=Object.keys(drafts).filter(k=>k!==context()&&Object.keys(drafts[k]||{}).length).filter(k=>{try{return JSON.parse(k)[0]===state.page||state.page==='settings'}catch(_){return false}});
   if(others.length){const box=el('div',{class:'panel'});box.append(el('p',{class:'muted'},'D’autres brouillons sont conservés sur ce téléphone.'));for(const k of others.slice(0,15)){const data=JSON.parse(k),button=el('button',{class:'action'},'Reprendre un brouillon · '+({jdr:'Notes',mental:'Carnet personnel',connected:'Atelier synchronisé',grimoire:'Cuisine'}[data[0]]||data[0]));button.onclick=()=>{state.page=data[0];if(data[1])tab=data[1];jdrEdit=data[2]||null;if(data[3])mentalCategory=data[3];openedRecipeId=data[4]||null;save();render()};box.append(button)}root.prepend(box)}
 }

 document.addEventListener('input',e=>{const node=e.target;if(!node.closest?.('#content')||!fields(node.closest('#content')).includes(node))return;(drafts[context()]||=Object.create(null))[signature(node)]=node.value;persist()},true);
 window.atelierDrafts={clearCurrent(){delete drafts[context()];persist()},clearContainer(root){const saved=drafts[context()];if(!saved||!root)return;for(const node of fields(root))delete saved[signature(node)];if(!Object.keys(saved).length)delete drafts[context()];persist()}};
 const previous=render;render=function(){previous();restore()};restore();
})();
